sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float strength;
half luma(half3 c) { return dot(c, half3(0.2126, 0.7152, 0.0722)); }
half l(float2 p) { return luma(image.eval(p).rgb); }
half4 main(float2 coord) {
    half gx = l(coord + float2(1, -1)) + 2 * l(coord + float2(1, 0)) + l(coord + float2(1, 1))
            - l(coord + float2(-1, -1)) - 2 * l(coord + float2(-1, 0)) - l(coord + float2(-1, 1));
    half gy = l(coord + float2(-1, 1)) + 2 * l(coord + float2(0, 1)) + l(coord + float2(1, 1))
            - l(coord + float2(-1, -1)) - 2 * l(coord + float2(0, -1)) - l(coord + float2(1, -1));
    half a = image.eval(coord).a;
    return half4(half3(saturate(length(half2(gx, gy)) * half(strength))) * a, a);
}
